from pathlib import Path
import subprocess,os,json,platform,hashlib
p=Path(__file__).resolve().parent;arch=platform.machine();r=Path('/tmp/xdiff/rustc.txt').read_text().strip();e=os.environ.copy();e['LD_LIBRARY_PATH']=Path('/tmp/xdiff/libdir.txt').read_text().strip()+':'+e.get('LD_LIBRARY_PATH','');x=subprocess.run([str(p/'probe'),'check','1'],env=e,capture_output=True,text=True,check=True);(p/('correctness.'+arch+'.json')).write_text(json.dumps({'command':x.args,'stdout':x.stdout,'exit_code':x.returncode},indent=2));out={}
for n,c in [('compiler',[r,'-vV']),('uname',['uname','-a']),('lscpu',['lscpu','-J']),('glibc',['ldd','--version']),('source_head',['git','-C','/tmp/xdiff-src','rev-parse','HEAD'])]:
 x=subprocess.run(c,env=e,capture_output=True,text=True);out[n]={'command':c,'stdout':x.stdout,'stderr':x.stderr,'exit_code':x.returncode}
files=list(p.glob('*.rs'))+[Path('/tmp/xdiff-src/library/coretests/benches/iter.rs')];out['source_sha256']={str(f):hashlib.sha256(f.read_bytes()).hexdigest()for f in files};b=next(x.strip()for x in Path('/tmp/xdiff/bins.txt').read_text().splitlines()if '/corebenches-'in x);out['benchmark_binary']={'path':b,'sha256':hashlib.sha256(Path(b).read_bytes()).hexdigest()};out['probe_binary_sha256']=hashlib.sha256((p/'probe').read_bytes()).hexdigest();(p/('environment.'+arch+'.json')).write_text(json.dumps(out,indent=2));print('checks and environment saved',arch)
